{"cells":[{"cell_type":"code","source":["\n","-- Test read from silver (attached or full path)\n","SELECT \n","    COUNT(*) as row_count,\n","    MIN(date) as earliest_date,\n","    MAX(date) as latest_date,\n","    COUNT(DISTINCT user_group) as unique_groups\n","FROM `silver_clean_data`.silver_cleaned_consumption;\n","\n","-- Sample rows\n","SELECT * \n","FROM `silver_cleaned_data`.silver_cleaned_consumption \n","LIMIT 5;\n"],"outputs":[],"execution_count":null,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"b4233c2e-4aaf-4678-a2dd-3a0a28ab9fc2"},{"cell_type":"code","source":["CREATE TABLE Dim_Date AS\n","SELECT DISTINCT \n","    date_key,\n","    date,\n","    year,\n","    quarter,\n","    month,\n","    day_of_month,\n","    day_of_week,\n","    week_of_year,\n","    day_name,\n","    month_name,\n","    is_weekend,\n","    season\n","FROM silver_clean_data.silver_cleaned_consumption\n","ORDER BY date_key;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":6,"statement_ids":[6],"state":"finished","livy_statement_state":"available","session_id":"26e50059-1208-470e-af46-fdd2feeb3b3f","normalized_state":"finished","queued_time":"2025-10-19T16:20:13.1918323Z","session_start_time":null,"execution_start_time":"2025-10-19T16:20:13.1930773Z","execution_finish_time":"2025-10-19T16:20:27.938073Z","parent_msg_id":"68ed7ff3-73da-4435-bba8-453778b1ec78"},"text/plain":"StatementMeta(, 26e50059-1208-470e-af46-fdd2feeb3b3f, 6, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":2,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}}],"execution_count":2,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"23901717-9522-45ef-8199-ea3993745a56"},{"cell_type":"code","source":["-- First, check if you have the numeric sorting columns\n","-- If they're missing, let's add them\n","\n","-- Add month number column (if missing)\n","ALTER TABLE dim_date \n","ADD COLUMN month_number INT;\n","\n","UPDATE dim_date\n","SET month_number = CASE \n","    WHEN month_name = 'January' THEN 1\n","    WHEN month_name = 'February' THEN 2\n","    WHEN month_name = 'March' THEN 3\n","    WHEN month_name = 'April' THEN 4\n","    WHEN month_name = 'May' THEN 5\n","    WHEN month_name = 'June' THEN 6\n","    WHEN month_name = 'July' THEN 7\n","    WHEN month_name = 'August' THEN 8\n","    WHEN month_name = 'September' THEN 9\n","    WHEN month_name = 'October' THEN 10\n","    WHEN month_name = 'November' THEN 11\n","    WHEN month_name = 'December' THEN 12\n","END;\n","\n","-- Add day of week number column (if missing)\n","ALTER TABLE dim_date \n","ADD COLUMN day_of_week_number INT;\n","\n","UPDATE dim_date\n","SET day_of_week_number = CASE \n","    WHEN day_name = 'Monday' THEN 1\n","    WHEN day_name = 'Tuesday' THEN 2\n","    WHEN day_name = 'Wednesday' THEN 3\n","    WHEN day_name = 'Thursday' THEN 4\n","    WHEN day_name = 'Friday' THEN 5\n","    WHEN day_name = 'Saturday' THEN 6\n","    WHEN day_name = 'Sunday' THEN 7\n","END;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":5,"statement_ids":[2,3,4,5],"state":"finished","livy_statement_state":"available","session_id":"17b363ab-89bb-488a-8645-48afe861c8a2","normalized_state":"finished","queued_time":"2025-11-03T09:29:56.69498Z","session_start_time":"2025-11-03T09:29:56.6952947Z","execution_start_time":"2025-11-03T09:30:05.5046894Z","execution_finish_time":"2025-11-03T09:30:54.2650101Z","parent_msg_id":"5a452e09-ef3c-453f-9f74-b67133ab453f"},"text/plain":"StatementMeta(, 17b363ab-89bb-488a-8645-48afe861c8a2, 5, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":1,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":1,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[{"name":"num_affected_rows","type":"long","nullable":true,"metadata":{}}]},"data":[["288"]]},"text/plain":"<Spark SQL result set with 1 rows and 1 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":1,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}},{"output_type":"execute_result","execution_count":1,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[{"name":"num_affected_rows","type":"long","nullable":true,"metadata":{}}]},"data":[["288"]]},"text/plain":"<Spark SQL result set with 1 rows and 1 fields>"},"metadata":{}}],"execution_count":1,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"aa3b6321-1a7f-4dbb-a469-89d61accd09e"},{"cell_type":"code","source":["CREATE TABLE Dim_UserGroup AS\n","SELECT DISTINCT \n","    user_group as user_group_id,\n","    user_group as user_group_name,\n","    'Business/Enterprise' as category,\n","    CONCAT('User Group ', user_group) as description\n","FROM silver_clean_data.silver_cleaned_consumption\n","ORDER BY user_group_id;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":10,"statement_ids":[10],"state":"finished","livy_statement_state":"available","session_id":"26e50059-1208-470e-af46-fdd2feeb3b3f","normalized_state":"finished","queued_time":"2025-10-19T16:22:54.4868661Z","session_start_time":null,"execution_start_time":"2025-10-19T16:22:54.4879047Z","execution_finish_time":"2025-10-19T16:23:19.1146902Z","parent_msg_id":"33cd7df8-5baf-458f-bf03-f69942343004"},"text/plain":"StatementMeta(, 26e50059-1208-470e-af46-fdd2feeb3b3f, 10, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":6,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}}],"execution_count":6,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"8640da42-1eda-4d69-a244-4b155319a23d"},{"cell_type":"code","source":["-- Update dim_usergroup with shorter, cleaner names\n","UPDATE dim_usergroup\n","SET user_group_name = CASE \n","    WHEN user_group_name LIKE '%Apartments, Apartment Block%' \n","        OR user_group_name = 'BE01' THEN 'Apartment Blocks'\n","    WHEN user_group_name LIKE '%Small Building (Electrically Heated)%' \n","        OR user_group_name = 'BE02' THEN 'Small Buildings (Heated)'\n","    WHEN user_group_name LIKE '%Small Building (Not Electrically Heated)%' \n","        OR user_group_name = 'BE03' THEN 'Small Buildings (Unheated)'\n","    WHEN user_group_name LIKE '%Holiday Home%' \n","        OR user_group_name = 'BE04' THEN 'Holiday Homes'\n","    WHEN user_group_name LIKE '%Residential Properties%' \n","        OR user_group_name = 'BE05' THEN 'Residential'\n","    WHEN user_group_name LIKE '%Agricultural Production%' \n","        OR user_group_name = 'BE06' THEN 'Agriculture'\n","    WHEN user_group_name = 'Industry' \n","        OR user_group_name = 'BE07' THEN 'Industry'\n","    WHEN user_group_name LIKE '%Infrastructure%' \n","        OR user_group_name = 'BE08' THEN 'Infrastructure'\n","    WHEN user_group_name = 'Construction' \n","        OR user_group_name = 'BE09' THEN 'Construction'\n","    WHEN user_group_name = 'Services' \n","        OR user_group_name = 'BE10' THEN 'Services'\n","    WHEN user_group_name LIKE '%Outdoor Lighting%' \n","        OR user_group_name = 'BE11' THEN 'Outdoor Lighting'\n","    WHEN user_group_name LIKE '%EV Charging%' \n","        OR user_group_name = 'BE12' THEN 'EV Charging'\n","    WHEN user_group_name = 'Traffic' \n","        OR user_group_name = 'BE13' THEN 'Traffic'\n","    WHEN user_group_name = 'Other' \n","        OR user_group_name = 'BE14' THEN 'Other'\n","    ELSE user_group_name\n","END;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":10,"statement_ids":[10],"state":"finished","livy_statement_state":"available","session_id":"127a7b08-4f10-4506-9b63-08d020d77240","normalized_state":"finished","queued_time":"2025-11-02T18:20:29.5961534Z","session_start_time":null,"execution_start_time":"2025-11-02T18:20:29.5972642Z","execution_finish_time":"2025-11-02T18:20:35.750052Z","parent_msg_id":"c6dd7302-fb95-46ba-9d2d-7a206250f436"},"text/plain":"StatementMeta(, 127a7b08-4f10-4506-9b63-08d020d77240, 10, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":9,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[{"name":"num_affected_rows","type":"long","nullable":true,"metadata":{}}]},"data":[["14"]]},"text/plain":"<Spark SQL result set with 1 rows and 1 fields>"},"metadata":{}}],"execution_count":9,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"78fb88f6-2175-48fb-8e78-79cbd31ea21f"},{"cell_type":"code","source":["CREATE TABLE Dim_Hour AS\n","SELECT DISTINCT \n","    hour_key,\n","    period_of_day,\n","    is_peak_hour,\n","    CASE \n","        WHEN is_peak_hour = 1 THEN 'Peak Hours'\n","        ELSE 'Off-Peak Hours'\n","    END as peak_description\n","FROM silver_clean_data.silver_cleaned_consumption\n","ORDER BY hour_key;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":8,"statement_ids":[8],"state":"finished","livy_statement_state":"available","session_id":"26e50059-1208-470e-af46-fdd2feeb3b3f","normalized_state":"finished","queued_time":"2025-10-19T16:21:52.9838657Z","session_start_time":null,"execution_start_time":"2025-10-19T16:21:52.9851138Z","execution_finish_time":"2025-10-19T16:21:59.0971067Z","parent_msg_id":"2f905eac-548c-4510-abfe-76b7ea2ea9bb"},"text/plain":"StatementMeta(, 26e50059-1208-470e-af46-fdd2feeb3b3f, 8, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":4,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}}],"execution_count":4,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"ec5fdbf1-13b7-4a23-b40f-209cbd170c2a"},{"cell_type":"code","source":["CREATE TABLE Fact_Consumption AS\n","SELECT \n","    date_key,\n","    hour_key,\n","    user_group as user_group_id,\n","    SUM(consumption_kwh) as total_consumption_kwh,\n","    SUM(accounting_points) as total_accounting_points,\n","    AVG(avg_per_point_kwh) as avg_consumption_per_point,\n","    MIN(consumption_kwh) as min_consumption_kwh,\n","    MAX(consumption_kwh) as max_consumption_kwh,\n","    COUNT(*) as record_count\n","FROM silver_clean_data.silver_cleaned_consumption\n","GROUP BY date_key, hour_key, user_group;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":9,"statement_ids":[9],"state":"finished","livy_statement_state":"available","session_id":"26e50059-1208-470e-af46-fdd2feeb3b3f","normalized_state":"finished","queued_time":"2025-10-19T16:22:13.8534236Z","session_start_time":null,"execution_start_time":"2025-10-19T16:22:13.8545426Z","execution_finish_time":"2025-10-19T16:22:20.5812112Z","parent_msg_id":"47a5f025-7e75-41f2-ab62-0f34a37c01a7"},"text/plain":"StatementMeta(, 26e50059-1208-470e-af46-fdd2feeb3b3f, 9, Finished, Available, Finished)"},"metadata":{}},{"output_type":"execute_result","execution_count":5,"data":{"application/vnd.synapse.sparksql-result+json":{"schema":{"type":"struct","fields":[]},"data":[]},"text/plain":"<Spark SQL result set with 0 rows and 0 fields>"},"metadata":{}}],"execution_count":5,"metadata":{"microsoft":{"language":"sparksql","language_group":"synapse_pyspark"},"collapsed":false},"id":"618ef1ab-0b30-45aa-87bd-c40be62534c2"},{"cell_type":"code","source":["-- Check row counts\n","SELECT 'Dim_Date' as table_name, COUNT(*) as row_count FROM Dim_Date\n","UNION ALL\n","SELECT 'Dim_UserGroup', COUNT(*) FROM Dim_UserGroup\n","UNION ALL\n","SELECT 'Dim_Hour', COUNT(*) FROM Dim_Hour\n","UNION ALL\n","SELECT 'Fact_Consumption', COUNT(*) FROM Fact_Consumption;\n","\n","-- Check date range in Dim_Date\n","SELECT \n","    MIN(date) as earliest_date,\n","    MAX(date) as latest_date,\n","    COUNT(*) as total_days\n","FROM Dim_Date;\n","\n","-- Check user groups\n","SELECT * FROM Dim_UserGroup ORDER BY user_group_id;\n","\n","-- Sample fact data\n","SELECT \n","    d.date,\n","    h.hour_key,\n","    h.period_of_day,\n","    u.user_group_name,\n","    f.total_consumption_kwh,\n","    f.total_accounting_points\n","FROM Fact_Consumption f\n","JOIN Dim_Date d ON f.date_key = d.date_key\n","JOIN Dim_Hour h ON f.hour_key = h.hour_key\n","JOIN Dim_UserGroup u ON f.user_group_id = u.user_group_id\n","ORDER BY d.date DESC, h.hour_key DESC\n","LIMIT 10;\n"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":14,"statement_ids":[11,12,13,14],"state":"finished","livy_statement_state":"available","session_id":"26e50059-1208-470e-af46-fdd2feeb3b3f","normalized_state":"finished","queued_time":"2025-10-19T16:23:49.3097513Z","session_start_time":null,"execu